do     --local luau = require("@lune/luau")     --local loadfn = luau.load     local MAX_OPS = 100000     local b     local loadfn = loadstring -- Lune already exposes loadstring, so we can use it directly, however we will proxy it     local gsub = ("").gsub     local typeof = typeof     local tostring = tostring     local error = error     local _debug = debug     local freeze = table.freeze     local _rawset = rawset     local _rawget = rawget     local _setmetatable = setmetatable     local _getmetatable = getmetatable     local ops = 0     local _setfenv = setfenv     local sbdbg = _setmetatable({}, { __metatable = false, __tostring = function()          ops += 1         if ops >= MAX_OPS then             return error("too many operations", 2)         end         return "debug"      end, __index = function(self, key)         ops += 1         if ops >= MAX_OPS then             return error("too many operations", 2)         end         if typeof(key) ~= "string" then             return error("not allowed", 2)         end;         if key == "info" then             return _debug.info         elseif key == "traceback" then             return _debug.traceback         else             return error("not supported", 2)         end         return nil -- should never reach here     end})     local fenvFnc = function()          ops += 1;         if ops >= MAX_OPS then             return error("too many operations", 2)         end         return b      end     local sfenv = function(fn, a)                     ops += 1                     if ops >= MAX_OPS then                         return error("too many operations", 2)                     end                     for i,v in next, a do                         if typeof(i) ~= "string" and typeof(i) ~= "number" then                             return error("not allowed", 2)                         end;                         if typeof(i) == "string" then                             i = gsub(i, "%z", "")                         end                         rawset(b, i, v)                     end                      return typeof(fn) == "function" and fn or nil                 end     debug = sbdbg     local lsf     local req = function(...)         return error("not allowed", 2)     end;     require = req;     local load_fn = function()         return error("not supported", 2)     end     local fakeRawGet = function(t, k)         ops += 1         if ops >= MAX_OPS then             return error("too many operations", 2)         end         return _rawget(t, k)     end     local fakeRawSet = function(t, k, v)         ops += 1         if ops >= MAX_OPS then             return error("too many operations", 2)         end         local mt = _getmetatable(t)         if typeof(mt) ~= "table" and typeof(mt) ~= "nil" and (typeof(mt) ~= "string" or mt ~= "super secret sandbox metatable") then             return error("not allowed", 2) -- prevent rawset on a protected __metatable table         end         mt = nil         return _rawset(t, k, v)     end     load = load_fn     local a = table.clone(getfenv())     getfenv = fenvFnc     b = _setmetatable({}, freeze({         __index = function(c, d)             ops += 1             if ops >= MAX_OPS then                 return error("too many operations", 2)             end             if typeof(d) ~= "string" and typeof(d) ~= "number" then                 return error("not allowed", 2)             end;             if typeof(d) == "number" then                 d = tostring(d)             end             d = gsub(d, "%z", "")             if d == "require" then                 return req             end;             if d == "loadstring" then                 return lsf             end;             if d == "load" then                 return load_fn             end;             if d == "debug" then                 return sbdbg             end;             if d == "getfenv" then                 return fenvFnc             end;             if d == "setfenv" then                 return sfenv             end;             if d == "rawget" then                 return fakeRawGet             end;             if d == "rawset" then                 return fakeRawSet             end;             return _rawget(b, d) or _rawget(a, d) or a[d]         end,         __newindex = function(c, d, e)             ops += 1             if ops >= MAX_OPS then                 return error("too many operations", 2)             end             _rawset(b, d, e)         end,         __tostring = function()             ops += 1             if ops >= MAX_OPS then                 return error("too many operations", 2)             end             return "sandbox"         end,         __metatable = "super secret sandbox metatable"     }))     _setfenv(0, b)     _setfenv(1, b)     setfenv = sfenv     lsf = function(...)         ops += 1         local f, e = loadfn(...)         return f and _setfenv(f, b) or nil, e     end;     loadstring = lsf     rawset = fakeRawSet     rawget = fakeRawGet endprint("hi")